#!/usr/bin/env python3
from pathlib import Path
p = Path('hub-ai.js')
t = p.read_text()
pairs = [("The ten shop laws: 1) Recover first — never vent. 2) Nut on the tube before you flare. 3) Dry nitrogen only. 4) Microns at the system, not a compound gauge. 5) Don't top off a leaker — recover, repair, evacuate, weigh in. 6) Lockout before ohms or µF. 7) Nameplate is law (MCA/MOP/charge). 8) SH = suction temp − evap sat; SC = cond sat − liquid temp. 9) Airflow before charge. 10) Lincoln Tech is home base — log it, teach the next helper. Open HVAC Commandments on the shop floor or ask me any one of them.", "The ten shop laws: 1) Recover first — never vent. 2) Nut on the tube before you flare. 3) Dry nitrogen only. 4) Microns at the system, not a compound gauge. 5) Don't top off a leaker — recover, repair, evacuate, weigh in. 6) Lockout before ohms or µF. 7) Nameplate is law (MCA/MOP/charge). 8) SH = suction line T − dew point; SC = start of boiling − liquid line T. 9) Airflow before charge. 10) Lincoln Tech is home base — log it, teach the next helper. Open HVAC Commandments on the shop floor or ask me any one of them."), ('High SH + low SC → undercharge/leak. High SH + high/normal SC → liquid-line restriction or TXV issue. Low SH + high SC → overcharge or low evaporator load/airflow on some systems. High head + high SC + high amps → dirty condenser or non-condensables. Low head + low suction both → severe undercharge or weak compressor. Always pair SH with SC. One number is a coin flip.', 'High SH + low SC → undercharge/leak — find the leak, do not top off, do not turn the TXV. High SH + high SC → restriction / plugged drier — cold at drier outlet, do not add gas. Low SH + high SC → overcharge — recover to nameplate. High head + SC about normal + high amps → dirty condenser — wash the coil, do not pull gas. High head AND high SC → air/noncondensables — recover, evacuate, weigh back. SH near zero with ice → airflow first, do not add gas. Always pair SH with SC. One number is a coin flip.'), ('Superheat = suction line temperature at the evaporator outlet (or compressor inlet, be consistent) minus saturated suction temperature from the PT chart at suction pressure. TXV systems often target moderate SH (OEM range). Fixed orifice often charged by superheat charts vs outdoor/indoor wet bulb. Low SH risks liquid floodback. High SH means starved evaporator.', 'Superheat = suction line T minus dew point (from the PT chart at suction pressure). TXV systems often target moderate SH (OEM range). Fixed orifice often charged by superheat charts vs outdoor/indoor wet bulb. Low SH risks liquid floodback. High SH means starved evaporator.'), ('Subcooling = saturated liquid temp from PT chart at liquid-line pressure minus actual liquid-line temperature. TXV systems are often charged by SC + weigh-in. High SC can mean overcharge or restricted condenser flow. Low SC often undercharge. Measure liquid line temp with good contact, out of direct sun when possible.', 'Subcooling = start of boiling minus liquid line T (from the PT chart at liquid-line pressure). TXV systems are often charged by SC + weigh-in. High SC can mean overcharge or air/noncondensables. Low SC often undercharge. Measure liquid line temp with good contact, out of direct sun when possible.'), ('High SH with healthy/high SC — liquid is in the condenser, evaporator is starved. Check drier delta-T, TXV bulb mount/powerhead, inlet screen. Replace drier anytime you open a burned-out or dirty system.', 'High SH and high SC — restriction / plugged drier. Cold at drier outlet. Do not add gas. TXV flash is at the seat, not the power head; stem in clockwise raises SH. Check drier delta-T, bulb strap, inlet screen. Replace drier anytime you open a burned-out or dirty system.'), ("High head, high SC, high amps. Clean coil, clear bushes, recheck. Don't remove charge to mask high head. 🔍 Scan unit photos often catch matted fins and juniper attacks.", 'High head, SC about normal, high amps. Wash the coil, clear bushes, recheck. Do not pull gas to mask high head. 🔍 Scan unit photos often catch matted fins and juniper attacks.'), ("Brown/dark texture dominance — outdoor or indoor coil likely fouled. High head, high SC, sad capacity. Clean the coil; don't 'fix' head pressure by recovering charge.", 'Brown/dark texture dominance — outdoor or indoor coil likely fouled. High head, SC about normal, sad capacity. Wash the coil; do not pull gas to mask head pressure.'), ("Lincoln Tech: SH = suction temp minus evap sat. SC = cond sat minus liquid temp. Read both or you're guessing.", "Lincoln Tech: SH = suction line T minus dew point. SC = start of boiling minus liquid line T. Read both or you're guessing.")]
for bad, good in pairs:
    if bad not in t:
        raise SystemExit('missing: ' + bad[:80])
    t = t.replace(bad, good, 1)
p.write_text(t)
assert 'dew point' in t and 'evap sat' not in t
assert 'clockwise raises SH' in t
assert 'SC about normal' in t
print('patched_ok', len(t))
